<script lang="ts">
import { goto } from '$app/navigation';
import { authClient } from '$lib/auth-client';
let email = $state(''); let password = $state(''); let busy = $state(false); let message = $state('');
async function submit(e: SubmitEvent) { e.preventDefault(); busy=true; message=''; try { const result = await authClient.signIn.email({email,password}); if(result.error) message=result.error.message ?? 'Sign-in failed'; else await goto('/dashboard'); } catch {message='Authentication is not configured or is unreachable';} finally {busy=false;} }
</script>
<svelte:head><title>Sign in · Kid Postgres</title></svelte:head><main class="auth-wrap"><form onsubmit={submit} class="auth-card"><a href="/" class="text-violet-300 text-sm">← Kid StarterPack</a><h1 class="text-3xl font-bold mt-6">Sign in.</h1><p class="text-slate-400 mt-2">Continue to your workspace.</p>{#if message}<p role="alert" class="alert">{message}</p>{/if}<label class="label" for="email">Email</label><input class="field" id="email" type="email" bind:value={email} autocomplete="email" required/><label class="label" for="password">Password</label><input class="field" id="password" type="password" bind:value={password} autocomplete="current-password" required minlength="8"/><button disabled={busy} class="primary w-full mt-6">{busy?'Signing in...':'Sign in'}</button><div class="text-center text-sm mt-6 text-slate-400"><a class="text-violet-300" href="/forgot-password">Forgot password?</a><br/><span class="inline-block mt-3">New here? <a href="/sign-up" class="text-violet-300">Create account</a></span></div></form></main>
